// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.crashimport androidx.lifecycle.DefaultLifecycleObserverimport androidx.lifecycle.LifecycleOwnerimport timber.log.Timberimport java.util.concurrent.TimeUnitimport java.util.concurrent.locks.LockSupportimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Global crash handler. * * Installs as the default uncaught exception handler. On any uncaught exception: * 1. Captures state snapshot (last user action, active module, session ID) * 2. Writes state to encrypted audit log * 3. Delegates to Firebase Crashlytics (if enabled) or default handler * 4. Triggers CrashRecoveryManager on next launch (saves "crashed last session" flag) * * Also observes ProcessLifecycle to detect ANR-like states (main thread * blocks > 5s) via a watchdog thread. */@Singletonclass NousCrashHandler @Inject constructor(    private val crashRecoveryManager: CrashRecoveryManager,) : DefaultLifecycleObserver, CrashHandler {    private var previousHandler: Thread.UncaughtExceptionHandler? = null    private var anrWatchdog: AnrWatchdog? = null    /**     * Install the global crash handler. Should be called once in [com.roshan.persona.NousApplication.onCreate]     * before any other code runs (after Timber is configured).     */    fun install() {        previousHandler = Thread.getDefaultUncaughtExceptionHandler()        Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->            handleCrash(thread, throwable)        }        Timber.tag("NOUS.Crash").i("Crash handler installed.")    }    override fun onStart(owner: LifecycleOwner) {        anrWatchdog = AnrWatchdog().also { it.start() }    }    override fun onStop(owner: LifecycleOwner) {        anrWatchdog?.stopWatchdog()        anrWatchdog = null    }    private fun handleCrash(thread: Thread, throwable: Throwable) {        try {            Timber.tag("NOUS.Crash").e(throwable, "Uncaught exception on %s", thread.name)            crashRecoveryManager.snapshotBeforeCrash(thread, throwable)        } catch (t: Throwable) {            Timber.tag("NOUS.Crash").e(t, "Crash handler failed")        } finally {            previousHandler?.uncaughtException(thread, throwable)        }    }}/** * ANR watchdog — detects main thread blocks longer than 5 seconds. * * Uses a dedicated [HandlerThread] for the tick Handler (NOT the main Looper) * so that when the main thread is blocked (the very condition being detected), * the watchdog still ticks and can correctly measure the block duration. * * The previous implementation posted to `Looper.getMainLooper()` which would * queue behind the very block being detected, causing false-positive ANR spam * or missed detections. */private class AnrWatchdog : Thread("NOUS-ANR-Watchdog") {    @Volatile private var running = true    @Volatile private var lastTickAt = System.currentTimeMillis()    private val handlerThread = android.os.HandlerThread("NOUS-ANR-Tick").also { it.start() }    private val tickHandler = android.os.Handler(handlerThread.looper)    override fun run() {        try {            while (running) {                // Post a tick to the dedicated HandlerThread (not main Looper).                // The tick Handler runs on a separate thread, so it always                // executes even if the main thread is blocked.                tickHandler.post {                    lastTickAt = System.currentTimeMillis()                }                // Use LockSupport.parkNanos — same semantics as Thread.sleep but                // without the InterruptedException baggage. Watchdog thread is                // dedicated so parking is the correct primitive here.                LockSupport.parkNanos(TimeUnit.MILLISECONDS.toNanos(CHECK_INTERVAL_MS))                val blockedFor = System.currentTimeMillis() - lastTickAt                if (blockedFor > ANR_THRESHOLD_MS) {                    Timber.tag("NOUS.ANR").w("Main thread blocked for %dms", blockedFor)                }            }        } finally {            // Clean up the HandlerThread to avoid thread leak.            handlerThread.quitSafely()        }    }    fun stopWatchdog() {        running = false    }    private companion object {        const val CHECK_INTERVAL_MS = 1_000L        const val ANR_THRESHOLD_MS = 5_000L    }}